export function ResponsiveTable({
  width = {{width}},
  showLabels = {{showLabels}},
  productName = "{{productName}}",
  accent = "{{accent}}",
}) {
  const cellLabel = (text) => showLabels ? `${text}` : "";
  return (
    <div style={{ width: "100%", maxWidth: 660 }}>
      <div style={{ width, maxWidth: "100%", containerType: "inline-size", background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, padding: 4, boxSizing: "border-box" }}>
        <div className="head" style={{ display: "none", justifyContent: "space-between", padding: "8px 10px", fontWeight: 700, fontSize: 11, color: "#241430aa", textTransform: "uppercase" }}>
          <span>Product</span><span>Qty</span><span>Price</span>
        </div>
        <div className="row" style={{ display: "flex", flexDirection: "column", padding: 10, fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430", background: "#fff", borderRadius: 8 }}>
          <span style={{ paddingLeft: 8, borderLeft: `3px solid ${accent}` }}>{cellLabel("Product: ")}{productName}</span>
          <span style={{ paddingLeft: 8, borderLeft: "3px solid transparent" }}>{cellLabel("Qty: ")}2</span>
          <span style={{ paddingLeft: 8, borderLeft: "3px solid transparent" }}>{cellLabel("Price: ")}&pound;18.00</span>
        </div>
      </div>
      <p style={{ margin: "8px 0 0", fontSize: 11, color: "#241430aa" }}>{width}px &mdash; rows stack into labelled fields below the container's threshold</p>
      <style>{`
        @container (min-width: 380px) {
          .head { display: flex !important; }
          .row { flex-direction: row; justify-content: space-between; }
        }
      `}</style>
    </div>
  );
}
